INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '0b9ec534-d44f-54e0-a2d4-e1908a9bdf8c', '773d8b95-845a-571a-a1f7-957c916a788a',
  '[L.O.1.2] Given a function:

```cpp
void func1(int arr[], int n){
    for(int i=n-1;i>=1;i--)
        for(int j=0; j<i;j++)
            if(arr[j]>arr[j+1])
                swap(arr[j], arr[j+1]); //Line 1
