    int i, tmp_sm;
    for(i=1; i<=n; i++){
        tmp_sm = foo(i);
        if(tmp_sm == sm)
            cnt++;
    }
    return cnt;
}
int main(){
    int n = 50, sum = 5;
    int ans = my_function(n, sum);
    cout << ans;
    return 0;
}
```

Lựa chọn:
- 4
- 5
- 6
- 7', 14
);

