  '9fc7cacd-2df0-5b64-9a1e-d5ed02a57cd0', '773d8b95-845a-571a-a1f7-957c916a788a',
  '[L.O.1.2] Please indicate the screen output of the following program:

```c
int cnt =0;
int foo(int n){
    if(n == 0)    return 0;
    return n % 10 + foo(n/10);
}
int my_function(int n, int sm){
    int i, tmp_sm;
    for(i=1;i<=n;i++){
        tmp_sm = foo(i);
        if(tmp_sm == sm)
            cnt++;
    }
    return cnt;
}
int main(){
    int n = 50, sum = 5;
    int ans = my_function(n,sum);
    cout << ans;
    return 0;
}
```

Lựa chọn:
- 4
- 5
- 6
- 7', 54
);

