```c
void insertionSort(int arr[], int array_size){
    int i, j, value;
    for (i = 1; i < array_size; i++){
        value = arr[i];
        j = i;
        while (________){
            arr[j] = arr[j - 1];
            j = j - 1;
        }
        arr[j] = value;
    }
}
```

